RUSTFLAGS=-Awarnings cargo test --package ripgrep --test integration -- multiline::replacement

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('crates/printer/src/util.rs')
source = path.read_text()
old = '''            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
'''
new = '''            // Keep look-ahead available to the matcher, but don't replace
            // matches or copy bytes beyond the matching lines.
            let mut last_match = range.start;
            matcher
                .captures_iter_at(subject, range.start, caps, |caps| {
                    let m = caps.get(0).unwrap();
                    if is_multi_line && m.start() >= range.end {
                        return false;
                    }
                    dst.extend_from_slice(&subject[last_match..m.start()]);
                    last_match = m.end();
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                })
                .map_err(io::Error::error_message)?;
            let end = if is_multi_line { range.end } else { subject.len() };
            dst.extend_from_slice(&subject[last_match..end]);
'''
assert source.count(old) == 1
path.write_text(source.replace(old, new))
path = Path('tests/multiline.rs')
source = path.read_text()
path.write_text(source.replace('});\n\n\nrgtest!(replacement_named_capture', '});\n\nrgtest!(replacement_named_capture'))
path = Path('CHANGELOG.md')
source = path.read_text()
needle = 'Bug fixes:\n\n'
assert needle in source
path.write_text(source.replace(needle, needle + '* Fix multiline replacements printing or replacing text beyond matching lines.\n', 1))
PY
